import { sequelize, LibraryMember, LibraryBook } from '../models/index.js';

await sequelize.sync({ force: true });

const sokha = await LibraryMember.create({ firstName: 'Sokha', lastName: 'Chan' });
const dune  = await LibraryBook.create({ title: 'Dune', author: 'Frank Herbert', publishedYear: 1965, pages: 412 });

// .addLibraryBook() is generated by belongsToMany
await sokha.addLibraryBook(dune);          // addLibraryBook(dune)

const favorites = await sokha.getLibraryBooks();          // getLibraryBooks()
console.log('Sokha favorites:', favorites.map(b => b.title));

await sequelize.close();